package com.fitlife.mfe.comunidade.bff.service;import com.fasterxml.jackson.databind.JsonNode;import com.fitlife.mfe.comunidade.bff.client.ApiGatewayClient;import java.util.Map;import org.springframework.http.HttpMethod;import org.springframework.stereotype.Service;
@Service public class ComunidadeBffService{private final ApiGatewayClient g;public ComunidadeBffService(ApiGatewayClient g){this.g=g;}public JsonNode listar(String id,String t){return g.exchange("/api/comunidade/eventos?usuarioId="+id,HttpMethod.GET,null,t);}public JsonNode meus(String id,String t){return g.exchange("/api/comunidade/eventos/usuario/"+id,HttpMethod.GET,null,t);}public JsonNode criar(JsonNode d,String t){return g.exchange("/api/comunidade/eventos",HttpMethod.POST,d,t);}public JsonNode editar(String id,JsonNode d,String t){return g.exchange("/api/comunidade/eventos/"+id,HttpMethod.PUT,d,t);}public JsonNode participar(String id,String usuario,String t){return g.exchange("/api/comunidade/eventos/"+id+"/participacoes",HttpMethod.POST,Map.of("usuarioId",usuario),t);}}
